import axios from "axios";
import MaterialTable, { MTableToolbar } from "material-table";
import React, { Component } from "react";
import { connect } from "react-redux";
import { Spinner } from "reactstrap";
import { tokenConfig } from "../../actions/authActions";
import store from "../../store";
import { changePage } from "../../actions/pageActions";
import {
  Checkbox,
  Snackbar,
  MuiAlert,
  Paper,
  Tab,
  Tabs,
  Box
} from "@material-ui/core";

class ClientDetail extends Component {
  state = {
    value: ""
  };
  handleChange = (event, newValue) => {
    this.setState({ value: newValue });
  };
  TabPanel = props => {
    const { children, value, index, ...other } = props;

    return (
      <div
        role="tabpanel"
        hidden={value !== index}
        id={`vertical-tabpanel-${index}`}
        aria-labelledby={`vertical-tab-${index}`}
        {...other}
      >
        {value === index && (
          <Box p={3}>
            <Typography>{children}</Typography>
          </Box>
        )}
      </div>
    );
  };
  render() {
    return (
      <Paper square>
        <Tabs
          value={this.state.value}
          orientation="vertical"
          indicatorColor="primary"
          textColor="primary"
          onChange={this.handleChange}
          centered
        >
          <Tab label="Billing" />
          <Tab label="Service Agreements" />
          <Tab label="Warranty" />
          <Tab label="Reports" />
          <Tab label="EU Features" />
          <Tab label="Service Agreements" />
          <Tab label="Requirements Documents" />
        </Tabs>

        <TabPanel value={this.value} index={0}>
          Page One
        </TabPanel>
        <TabPanel value={this.value} index={1}>
          Page Two
        </TabPanel>
        <TabPanel value={this.value} index={2}>
          Page Three
        </TabPanel>
      </Paper>
    );
  }
}

const mapStateToProps = state => ({
  auth: state.auth
});

export default connect(mapStateToProps, { changePage })(ClientDetail);
